import heapq


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers = {}
        self._tickets = {}
        self._queue = []
        self._next_id = 1

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def open_ticket(
        self,
        customer: str,
        title: str,
        priority: str = "normal",
        description: str = "",
    ) -> int:
        """Open a ticket; returns its id."""
        if not title:
            raise ValueError("Ticket title cannot be empty")
        if priority not in self.PRIORITIES:
            raise ValueError("Invalid priority")

        vip = self._customers[customer]
        ticket_id = self._next_id
        self._next_id += 1

        order = (not vip, -self.PRIORITIES.index(priority), ticket_id)
        self._tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "description": description,
            "order": order,
            "status": "queued",
        }
        heapq.heappush(self._queue, order)
        return ticket_id

    def ticket(self, ticket_id: int) -> dict:
        """Return a copy of the ticket's data."""
        ticket = self._tickets[ticket_id]
        return {key: value for key, value in ticket.items() if key != "order"}

    def tickets_of(self, customer: str) -> list[int]:
        """Return the ids of the customer's tickets."""
        return [
            ticket_id
            for ticket_id, ticket in self._tickets.items()
            if ticket["customer"] == customer
        ]

    def next_ticket(self) -> int | None:
        """Take the next ticket out of the queue, or return None if empty."""
        while self._queue:
            _, _, ticket_id = heapq.heappop(self._queue)
            ticket = self._tickets[ticket_id]
            if ticket["status"] == "queued":
                ticket["status"] = "in_progress"
                return ticket_id
        return None

    def queue_length(self) -> int:
        """Return the number of tickets waiting in the queue."""
        return sum(ticket["status"] == "queued" for ticket in self._tickets.values())

    def close(self, ticket_id: int) -> None:
        self._tickets[ticket_id]["status"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        """Put a ticket back into the queue."""
        ticket = self._tickets[ticket_id]
        if ticket["status"] == "closed":
            raise ValueError("A closed ticket cannot be reopened")
        if ticket["status"] != "queued":
            ticket["status"] = "queued"
            heapq.heappush(self._queue, ticket["order"])
